  "design": "design/geo_hp_chiller_v4",
  "changes": [
    {
      "path": "params.compression_cooler.temperature_setpoint",
      "value": {
        "unit": "degC",
        "value": 25
      },
      "reason": "The dry cooler holds the condenser loop at the chiller's sink outlet: case site.air.temperature 10 degC plus the cooling engineer's 15 K approach = 25 degC, which stays above the 20 degC chilled-water supply so the chiller can reject.",
      "source": "case site.air.temperature + assumption (cooler approach 15 K, energy systems engineer II)"
    }
  ],
  "name": "geo_hp_chiller_v5"
}

