What the call sends:
{
  "design": "design/geo_hp_chiller_v7",
  "changes": [
    {
      "path": "params.compression_cooler.loop_pressure",
      "value": {
        "unit": "bar",
        "value": 4
      },
      "reason": "Static pressure the closed condenser loop is held at; 4 bar keeps the loop above atmospheric at the cooler's 25 degC setpoint and matches the case's 4 bar cooling-network pressure level.",
      "source": "case demand.cooling.return_pressure (loop held at the same pressure level)"
    },
    {
      "path": "params.compression_cooler.flow",
      "value": {
        "unit": "kg/s",
        "value": 300
      },
      "reason": "Condenser-loop mass flow sized to keep the loop temperature rise small at the 10 MW chiller duty, so the cooler holds its 25 degC setpoint; design value to confirm with the cooler vendor.",
      "source": "assumption (condenser loop flow, energy systems engineer II)"
    }
  ],
  "name": "geo_hp_chiller_v8"
}

